css:
/* Common styles from student-dashboard.html */
    body { margin: 0; font-family: 'Inter', Arial, sans-serif; background: #f3f6fa; color: #222; }
    .layout { display: flex; min-height: 100vh; }

    /* Visually hidden (for accessibility) */
    .visually-hidden {
      position: absolute;
      left: -10000px;
      top: auto;
      width: 1px;
      height: 1px;
      overflow: hidden;
    }

    /* Sidebar styles (copied from student-dashboard.html) */
    .sidebar {
      width: 250px;
      background: #1a202c;
      color: #fff;
      display: flex;
      flex-direction: column;
      padding: 32px 0 24px 0;
      box-shadow: 2px 0 16px rgba(30,58,138,0.07);
    }
    .sidebar nav ul { list-style: none; padding: 0; margin: 0; }
    .sidebar nav ul li {
      display: flex;
      align-items: center;
      gap: 16px;
      padding: 14px 32px;
      font-size: 1.08rem;
      border-radius: 8px;
      margin-bottom: 6px;
      cursor: pointer;
      transition: background 0.15s;
      opacity: 0.85;
    }
    .sidebar nav ul li.active, .sidebar nav ul li:hover {
      background: #2d3748;
      opacity: 1;
    }
    .sidebar nav ul li a {
      color: inherit;
      text-decoration: none;
      display: flex;
      align-items: center;
      gap: 16px;
      width: 100%;
      height: 100%;
      font-weight: 500;
    }
    .sidebar nav ul li.menu-divider {
      padding: 8px 32px;
      font-size: 0.85rem;
      color: #64748b;
      text-transform: uppercase;
      letter-spacing: 0.05em;
      margin-top: 1rem;
      cursor: default;
      opacity: 0.7;
    }

    /* Main content styles */
    .main-content {
      flex: 1;
      padding: 2rem;
    }

    .page-header {
      display: flex;
      justify-content: space-between;
      align-items: center;
      margin-bottom: 2rem;
    }

    .page-title {
      font-size: 1.5rem;
      color: #1e3a8a;
      display: flex;
      align-items: center;
      gap: 0.5rem;
    }

    .search-bar {
      display: flex;
      gap: 1rem;
      margin-bottom: 2rem;
    }

    .search-input {
      flex: 1;
      padding: 0.8rem 1rem;
      border: 1px solid #e2e8f0;
      border-radius: 8px;
      font-size: 1rem;
      outline: none;
    }

    .subject-filter {
      padding: 0.8rem 1rem;
      border: 1px solid #e2e8f0;
      border-radius: 8px;
      font-size: 1rem;
      outline: none;
    }

    .add-formula-btn {
      padding: 0.8rem 1.5rem;
      background: #2563eb;
      color: white;
      border: none;
      border-radius: 8px;
      font-weight: 600;
      cursor: pointer;
      transition: background 0.2s;
    }

    .add-formula-btn:hover {
      background: #1d4ed8;
    }

    .formulas-grid {
      display: grid;
      grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
      gap: 1.5rem;
    }

    .formula-card {
      background: white;
      border-radius: 12px;
      padding: 1.5rem;
      box-shadow: 0 2px 12px rgba(30,58,138,0.07);
    }

    .formula-subject {
      font-size: 0.9rem;
      color: #2563eb;
      font-weight: 600;
      margin-bottom: 0.5rem;
      display: flex;
      justify-content: space-between;
      align-items: center;
    }

    .formula-subject::after {
      content: attr(data-category);
      font-size: 0.8rem;
      color: #64748b;
      background: #f1f5f9;
      padding: 0.2rem 0.5rem;
      border-radius: 4px;
    }

    .formula-title {
      font-size: 1.1rem;
      color: #1e3a8a;
      margin-bottom: 1rem;
    }

    .formula-content {
      padding: 1rem;
      background: #f8fafc;
      border-radius: 8px;
      font-family: 'Courier New', monospace;
      margin-bottom: 1rem;
    }

    .formula-actions {
      display: flex;
      justify-content: flex-end;
      gap: 0.5rem;
    }

    .formula-btn {
      padding: 0.5rem;
      border: none;
      background: none;
      color: #64748b;
      cursor: pointer;
      transition: color 0.2s;
    }

    .formula-btn:hover {
      color: #2563eb;
    }

    /* Modal Styles */
    .modal-overlay {
      position: fixed;
      top: 0;
      left: 0;
      right: 0;
      bottom: 0;
      background: rgba(0, 0, 0, 0.5);
      display: none;
      justify-content: center;
      align-items: center;
      z-index: 1000;
    }

    .modal {
      background: white;
      border-radius: 12px;
      padding: 2rem;
      width: 90%;
      max-width: 500px;
      box-shadow: 0 4px 24px rgba(0, 0, 0, 0.15);
    }

    .modal-header {
      display: flex;
      justify-content: space-between;
      align-items: center;
      margin-bottom: 1.5rem;
    }

    .modal-title {
      font-size: 1.3rem;
      color: #1e3a8a;
      font-weight: 600;
    }

    .modal-close {
      background: none;
      border: none;
      font-size: 1.5rem;
      cursor: pointer;
      color: #64748b;
    }

    .modal-form {
      display: flex;
      flex-direction: column;
      gap: 1rem;
    }

    .form-group {
      display: flex;
      flex-direction: column;
      gap: 0.5rem;
    }

    .form-group label {
      font-weight: 500;
      color: #1e3a8a;
    }

    .form-group input,
    .form-group select,
    .form-group textarea {
      padding: 0.8rem;
      border: 1px solid #e2e8f0;
      border-radius: 8px;
      font-size: 1rem;
      outline: none;
    }

    .form-group textarea {
      font-family: 'Courier New', monospace;
      min-height: 100px;
      resize: vertical;
    }

    .modal-actions {
      display: flex;
      justify-content: flex-end;
      gap: 1rem;
      margin-top: 1.5rem;
    }

    .modal-btn {
      padding: 0.8rem 1.5rem;
      border-radius: 8px;
      font-weight: 600;
      cursor: pointer;
      transition: all 0.2s;
    }

    .modal-btn.cancel {
      background: #f1f5f9;
      border: none;
      color: #64748b;
    }

    .modal-btn.save {
      background: #2563eb;
      border: none;
      color: white;
    }

    .modal-btn:hover {
      transform: translateY(-1px);
    }
